<section class="admin-welcome"><div><h1><?= htmlspecialchars($title) ?></h1><p>Données enregistrées et mises à jour par la plateforme.</p></div></section><section class="panel"><div class="table-toolbar"><label class="search"><i data-icon="search"></i><input data-table-search placeholder="Rechercher..."></label><span><?= count($items) ?> résultat<?= count($items)>1?'s':'' ?></span></div><div class="table-responsive"><table><thead><tr><?php if($type==='orders'): ?><th>RÉFÉRENCE</th><th>CLIENT</th><th>TOTAL</th><th>PAIEMENT</th><th>STATUT</th><th>DATE</th><?php elseif($type==='users'): ?><th>NOM</th><th>EMAIL</th><th>RÔLE</th><th>STATUT</th><?php else: ?><th>PRODUIT</th><th>STOCK</th><th>PRIX</th><th>RÉFÉRENCE</th><?php endif ?></tr></thead><tbody><?php foreach($items as $item): ?><tr data-search-row><?php if($type==='orders'): ?><td><strong><?= htmlspecialchars($item['reference']) ?></strong></td><td><?= htmlspecialchars($item['customer']) ?><br><small><?= htmlspecialchars($item['email']) ?></small></td><td><?= number_format($item['total'],0,',',' ') ?> F</td><td><?= htmlspecialchars($item['payment']) ?></td><td><span class="status published"><?= htmlspecialchars($item['status']) ?></span></td><td><?= date('d/m/Y H:i',strtotime($item['created_at'])) ?></td><?php elseif($type==='users'): ?><td><strong><?= htmlspecialchars($item['name']) ?></strong></td><td><?= htmlspecialchars($item['email']) ?></td><td><?= htmlspecialchars($item['role']) ?></td><td><span class="status published"><?= htmlspecialchars($item['status']) ?></span></td><?php else: ?><td><strong><?= htmlspecialchars($item['title']) ?></strong></td><td><?= htmlspecialchars($item['stock']) ?></td><td><?= $item['price']?number_format($item['price'],0,',',' ').' F':'Sur devis' ?></td><td><?= htmlspecialchars($item['id']) ?></td><?php endif ?></tr><?php endforeach ?></tbody></table></div><?php if(!$items): ?><div class="admin-empty">Aucune donnée enregistrée pour le moment.</div><?php endif ?></section>
